use test_programs::preview1::open_scratch_directory;

const FILENAME: &str = "test.txt";
const CONTENTS: &[u8] = b"truncation test file\n";

unsafe fn test_readonly_truncation(dir_fd: wasip1::Fd) {
    // Attempt to truncate an existing file via `O_TRUNC`. The directory was
    // preopened with read-only file permissions (`FilePerms::READ`), so the
    // runtime must reject the truncation rather than silently emptying the
    // file.
    let result = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        wasip1::OFLAGS_TRUNC,
        wasip1::RIGHTS_FD_READ,
        wasip1::RIGHTS_FD_READ,
        0,
    );
    assert!(
        result.is_err(),
        "truncating a read-only file must return an error"
    );

    // If the runtime opened a descriptor anyway, close it so we don't leak it.
    if let Ok(fd) = result {
        wasip1::fd_close(fd).expect("closing the file");
    }

    // Re-open the file read-only and confirm the contents are unchanged, i.e.
    // that no truncation took place.
    let file_fd = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        0,
        wasip1::RIGHTS_FD_READ,
        wasip1::RIGHTS_FD_READ,
        0,
    )
    .expect("opening the file for reading");

    let mut buffer = [0u8; 128];
    let nread = wasip1::fd_read(
        file_fd,
        &[wasip1::Iovec {
            buf: buffer.as_mut_ptr(),
            buf_len: buffer.len(),
        }],
    )
    .expect("reading file content");

    assert_eq!(
        &buffer[..nread],
        CONTENTS,
        "file contents must be unchanged after a rejected truncation"
    );

    wasip1::fd_close(file_fd).expect("closing the file");
}

fn main() {
    // Open the preopened read-only directory.
    let dir_fd = match open_scratch_directory("readonly") {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{err}");
            std::process::exit(1)
        }
    };

    unsafe {
        test_readonly_truncation(dir_fd);
    }
}
