[metadata] {"type": "create", "filePath": "/workspace/repo/crates/wasi/examples/verify_trunc.rs", "content": "//! Temporary end-to-end verification of read-only truncation rejection.

use wasmtime::component::{Component, Linker, ResourceTable};
use wasmtime::{Engine, Store};
use wasmtime_wasi::p2::bindings::sync::Command;
use wasmtime_wasi::p2::add_to_linker_sync;
use wasmtime_wasi::{DirPerms, FilePerms, WasiCtx, WasiCtxBuilder, WasiCtxView, WasiView};
use test_programs_artifacts::*;

const CONTENTS: &[u8] = b"truncation test file\n";

struct Ctx {
    wasi: WasiCtx,
    table: ResourceTable,
}
impl WasiView for Ctx {
    fn ctx(&mut self) -> WasiCtxView<'_> {
        WasiCtxView { ctx: &mut self.wasi, table: &mut self.table }
    }
}

fn run_component(name: &str, path: &str) {
    let td = tempfile::tempdir().unwrap();
    let file_path = td.path().join("test.txt");
    std::fs::write(&file_path, CONTENTS).unwrap();

    let engine = Engine::default();
    let mut linker = Linker::new(&engine);
    add_to_linker_sync(&mut linker).unwrap();

    let mut builder = WasiCtxBuilder::new();
    builder.args(&[name, "readonly"]);
    builder
        .preopened_dir(td.path(), "readonly", DirPerms::READ | DirPerms::MUTATE, FilePerms::READ)
        .unwrap();
    let ctx = Ctx { wasi: builder.build(), table: ResourceTable::new() };
    let mut store = Store::new(&engine, ctx);

    let component = Component::from_file(&engine, path).unwrap();
    let command = Command::instantiate(&mut store, &component, &linker).unwrap();
    command
        .wasi_cli_run()
        .call_run(&mut store)
        .unwrap()
        .map_err(|()| "guest returned failure")
        .unwrap();

    let after = std::fs::read(&file_path).unwrap();
    assert_eq!(after, CONTENTS, "{name}: file must be unchanged on host");
    println!("{name}: OK, file unchanged ({} bytes)", after.len());
}

fn main() {
    run_component("p1_file_truncation_readonly", P1_FILE_TRUNCATION_READONLY_COMPONENT);
    run_component("p2_file_truncation_readonly", P2_FILE_TRUNCATION_READONLY_COMPONENT);
    println!("ALL OK");
}
